item.content:encoded:
@media (max-width: 768px) {
    /* Target the specific 'Login' submenu by its parent LI's ID */
    #menu-item-562 > .sub-menu {
        display: flex;
        flex-direction: column;
        position: static;
        width: 100%;
        box-shadow: none;
        background-color: transparent;
        padding: 0;
        border-radius: 0;
        margin-top: 5px;
        margin-bottom: 5px;
    }

    #menu-item-YOUR_LOGIN_MENU_ITEM_ID > .sub-menu li {
        width: 100%;
        padding-left: 20px; /* Indent submenu items */
        box-sizing: border-box;
    }

    #menu-item-YOUR_LOGIN_MENU_ITEM_ID > .sub-menu a {
        background-color: #f9f9f9;
        border-left: 3px solid #ddd;
    }

    #menu-item-YOUR_LOGIN_MENU_ITEM_ID > .sub-menu a:hover {
        background-color: #e0e0e0;
    }
}
/* Root Variables for Jenga365 Branding */
:root {
    --white: #FFFFFF;
    --black: #000000;
    --red: #FF0000;
    --green: #00FF00;
}

/* Reset and Base Styles */
html {
    line-height: 1.15;
    -webkit-text-size-adjust: 100%;
}

*, :after, :before {
    box-sizing: border-box;
}

body {
    background-color: var(--white);
    color: #333;
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans", sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol", "Noto Color Emoji";
    font-size: 1rem;
    font-weight: 400;
    line-height: 1.5;
    margin: 0;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
    color: inherit;
    font-family: inherit;
    font-weight: 500;
    line-height: 1.2;
    margin-block-start: .5rem;
    margin-block-end: 1rem;
}

h1 { font-size: 2.5rem; }
h2 { font-size: 2rem; }
h3 { font-size: 1.75rem; }
h4 { font-size: 1.5rem; }
h5 { font-size: 1.25rem; }
h6 { font-size: 1rem; }

p {
    margin-block-start: 0;
    margin-block-end: .9rem;
}

a {
    background-color: transparent;
    color: #c36;
    text-decoration: none;
}

a:hover {
    color: #336;
}

a:not([href]):not([tabindex]),
a:not([href]):not([tabindex]):focus,
a:not([href]):not([tabindex]):hover {
    color: inherit;
    text-decoration: none;
}

a:not([href]):not([tabindex]):focus {
    outline: 0;
}

.screen-reader-text {
    clip: rect(1px, 1px, 1px, 1px);
    height: 1px;
    overflow: hidden;
    position: absolute !important;
    width: 1px;
    word-wrap: normal !important;
}

.screen-reader-text:focus {
    background-color: #eee;
    clip: auto !important;
    clip-path: none;
    color: #333;
    display: block;
    font-size: 1rem;
    height: auto;
    left: 5px;
    line-height: normal;
    padding: 12px 24px;
    text-decoration: none;
    top: 5px;
    width: auto;
    z-index: 100000;
}

/* WordPress-Style Buttons */
.wp-core-ui .button,
.wp-core-ui .button-primary,
.wp-core-ui .button-secondary {
    display: inline-block;
    text-decoration: none;
    font-size: 13px;
    line-height: 2.15384615; /* 28px */
    min-height: 30px;
    margin: 0;
    padding: 0 10px;
    cursor: pointer;
    border-width: 1px;
    border-style: solid;
    -webkit-appearance: none;
    border-radius: 3px;
    white-space: nowrap;
    box-sizing: border-box;
}

.wp-core-ui button::-moz-focus-inner,
.wp-core-ui input[type="submit"]::-moz-focus-inner {
    border-width: 0;
    border-style: none;
    padding: 0;
}

.wp-core-ui .button.button-large,
.wp-core-ui .button-group.button-large .button {
    min-height: 32px;
    line-height: 2.30769231; /* 30px */
    padding: 0 12px;
}

.wp-core-ui .button.button-small,
.wp-core-ui .button-group.button-small .button {
    min-height: 26px;
    line-height: 2.18181818; /* 24px */
    padding: 0 8px;
    font-size: 11px;
}

.wp-core-ui .button,
.wp-core-ui .button-secondary {
    color: #2271b1;
    border-color: #2271b1;
    background: #f6f7f7;
    vertical-align: top;
}

.wp-core-ui .button:hover,
.wp-core-ui .button-secondary:hover {
    background: #f0f0f1;
    border-color: #0a4b78;
    color: #0a4b78;
}

.wp-core-ui .button:focus,
.wp-core-ui .button-secondary:focus {
    background: #f6f7f7;
    border-color: #3582c4;
    color: #0a4b78;
    box-shadow: 0 0 0 1px #3582c4;
    outline: 2px solid transparent;
    outline-offset: 0;
}

.wp-core-ui .button:active,
.wp-core-ui .button-secondary:active {
    background: #f6f7f7;
    border-color: #8c8f94;
    box-shadow: none;
}

.wp-core-ui .button-primary {
    background: #2271b1;
    border-color: #2271b1;
    color: var(--white);
    text-decoration: none;
    text-shadow: none;
}

.wp-core-ui .button-primary:hover,
.wp-core-ui .button-primary:focus {
    background: #135e96;
    border-color: #135e96;
    color: var(--white);
}

.wp-core-ui .button-primary:focus {
    box-shadow: 0 0 0 1px var(--white), 0 0 0 3px #2271b1;
}

.wp-core-ui .button-primary:active {
    background: #135e96;
    border-color: #135e96;
    box-shadow: none;
    color: var(--white);
}

.wp-core-ui .button[disabled],
.wp-core-ui .button:disabled,
.wp-core-ui .button-secondary[disabled],
.wp-core-ui .button-secondary:disabled {
    color: #a7aaad !important;
    background: #f6f7f7 !important;
    border-color: #dcdcde !important;
    box-shadow: none !important;
    cursor: default;
}

/* Ultimate Member Button Styles */
.um .um-button,
.um a.um-button,
.um input[type=submit].um-button {
    font-family: 'Montserrat', sans-serif;
    font-weight: bold;
    font-size: 14px;
    border-radius: 8px;
    padding: 10px 20px;
    transition: all 0.3s ease;
}

.um .um-button.um-login,
.um input[type=submit].um-button[value="Login"],
.um a.um-button[href*="login"] {
    background: var(--black) !important;
    color: var(--white) !important;
}

.um .um-button.um-login:hover,
.um input[type=submit].um-button[value="Login"]:hover,
.um a.um-button[href*="login"]:hover {
    background: var(--black) !important;
    color: var(--white) !important;
}

.um .um-button.um-alt,
.um a.um-button.um-alt,
.um input[type=submit].um-button.cancel,
.um a.um-button[href*="cancel"] {
    background: var(--red) !important;
    color: var(--white) !important;
}

.um .um-button.um-alt:hover,
.um a.um-button.um-alt:hover,
.um input[type=submit].um-button.cancel:hover,
.um a.um-button[href*="cancel"]:hover {
    background: var(--black) !important;
    color: var(--white) !important;
}

.um .um-button.um-register,
.um input[type=submit].um-button[value="Register"],
.um a.um-button[href*="register"],
.um .meetup-btn {
    background: var(--black) !important;
    color: var(--white) !important;
}

.um .um-button.um-register:hover,
.um input[type=submit].um-button[value="Register"]:hover,
.um a.um-button[href*="register"]:hover,
.um .meetup-btn:hover {
    background: var(--green) !important;
    color: var(--black) !important;
}

.meetup-btn {
    background: var(--black) !important;
    color: var(--white) !important;
    font-family: 'Montserrat', sans-serif;
    font-weight: bold;
    border-radius: 8px;
    padding: 10px 20px;
    display: inline-flex;
    align-items: center;
    text-decoration: none;
}

.meetup-btn i {
    margin-right: 8px;
}

.meetup-btn:hover {
    background: var(--green) !important;
    color: var(--black) !important;
}

/* Ultimate Member Directory Search Button */
.um-directory .um-member-directory-header .um-member-directory-search-line .um-do-search {
    background-color: var(--white) !important;
    border: 1px solid var(--black) !important;
    color: var(--black) !important;
    font-family: 'Montserrat', sans-serif !important;
    font-weight: bold !important;
    font-size: 14px !important;
    border-radius: 8px !important;
    padding: 15px 15px !important;
    min-height: 10px !important;
    line-height: 0.8 !important;
    text-align: center !important;
    transition: all 0.3s ease !important;
    cursor: pointer !important;
    -webkit-appearance: none !important;
    white-space: nowrap !important;
    width: auto !important;
    min-width: 10% !important;
    box-shadow: none !important;
}

.um-directory .um-member-directory-header .um-member-directory-search-line .um-do-search:hover,
.um-directory .um-member-directory-header .um-member-directory-search-line .um-do-search:focus {
    background-color: var(--black) !important;
    border-color: var(--white) !important;
    color: var(--white) !important;
}

/* Ensure Search Form Layout Consistency */
.um-directory .um-member-directory-header .um-member-directory-search-line {
    max-width: 294px;
    position: relative;
    margin: 1.5rem auto;
}

.um-directory .um-member-directory-header .um-member-directory-search-line input[type="search"] {
    border: 1px solid #666 !important;
    border-radius: 3px !important;
    padding: .5rem 1rem .5rem 2.5rem !important;
    transition: all 0.3s ease !important;
    width: 100% !important;
    font-family: 'Montserrat', sans-serif !important;
    font-size: 15px !important;
}

.um-directory .um-member-directory-header .um-member-directory-search-line input[type="search"]:focus {
    border-color: #333 !important;
}
/* Responsive Design */
@media (max-width: 768px) {
    h1 {
        font-size: 1.5rem;
    }
    p {
        font-size: 1rem;
    }
    .um-search-form {
        max-width: 100%;
    }
    /* Login Submenu Styling */
    #menu-item-562 > .sub-menu {
        display: flex;
        flex-direction: column;
        position: static;
        width: 100%;
        box-shadow: none;
        background-color: transparent;
        padding: 0;
        border-radius: 0;
        margin-top: 5px;
        margin-bottom: 5px;
    }
    #menu-item-562 > .sub-menu li {
        width: 100%;
        padding-left: 20px;
        box-sizing: border-box;
    }
    #menu-item-562 > .sub-menu a {
        background-color: #f9f9f9;
        border-left: 3px solid #ddd;
    }
    #menu-item-562 > .sub-menu a:hover {
        background-color: #e0e0e0;
    }
}

@media screen and (max-width: 782px) {
    .wp-core-ui .button,
    .wp-core-ui .button.button-large,
    .wp-core-ui .button.button-small {
        padding: 0 14px;
        line-height: 2.71428571; /* 38px */
        font-size: 14px;
        min-height: 40px;
        margin-bottom: 4px;
    }
    .um-search-form .um-search-submit {
        padding: 0 14px !important;
        line-height: 2.71428571 !important;
        font-size: 14px !important;
        min-height: 40px !important;
    }
}

/* Print Styles */
@media print {
    *, :after, :before {
        background: transparent !important;
        box-shadow: none !important;
        color: #000 !important;
        text-shadow: none !important;
    }
    a, a:visited {
        text-decoration: underline;
    }
    a[href]:after {
        content: " (" attr(href) ")";
    }
    a[href^="#"]:after,
    a[href^="javascript:"]:after {
        content: "";
    }
}

wp:postmeta.wp:meta_value:
[{"id":"3b45de9f","elType":"container","settings":[],"elements":[{"id":"536c4402","elType":"widget","settings":{"editor":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Privacy Policy - Jenga365</title>
    <link href="https://fonts.googleapis.com/css2?family=Montserrat:wght@400;600&display=swap" rel="stylesheet">
    <style>
        /* Root Variables for Jenga365 Branding */
        :root {
            --white: #FFFFFF;
            --black: #000000;
            --red: #FF0000;
            --green: #00FF00;
            --light-grey: #f5f5f5;
        }

        /* Base Styles */
        body {
            background-color: var(--light-grey);
            color: #333;
            font-family: 'Montserrat', sans-serif;
            font-size: 1rem;
            font-weight: 400;
            line-height: 1.6;
            margin: 0;
            -webkit-font-smoothing: antialiased;
            -moz-osx-font-smoothing: grayscale;
        }

        .privacy-policy-container {
            max-width: 960px;
            margin: 2rem auto;
            padding: 20px;
            background-color: var(--white);
            border-radius: 8px;
            display: flex;
            gap: 2rem;
        }

        /* Sidebar Table of Contents */
        .table-of-contents {
            flex: 0 0 240px;
            position: sticky;
            top: 20px;
            align-self: flex-start;
            padding: 1rem;
            background-color: var(--light-grey);
            border-radius: 8px;
        }

        .table-of-contents h2 {
            font-size: 1.25rem;
            font-weight: 600;
            color: var(--black);
            margin: 0 0 1rem;
        }

        .table-of-contents ul {
            list-style-type: none;
            margin: 0;
            padding: 0;
        }

        .table-of-contents li {
            margin: 0.5rem 0;
        }

        .table-of-contents a {
            font-size: 0.95rem;
            font-weight: 600;
            color: #c36;
            text-decoration: none;
            display: block;
            padding: 0.5rem;
            border-radius: 4px;
            transition: all 0.3s ease;
        }

        .table-of-contents a:hover,
        .table-of-contents a.active {
            background-color: var(--green);
            color: var(--white);
        }

        /* Main Content */
        .content {
            flex: 1;
        }

        .content h1 {
            font-size: 2.25rem;
            font-weight: 600;
            color: var(--black);
            margin: 0 0 1rem;
        }

        .last-updated {
            font-size: 0.9rem;
            color: #666;
            margin-bottom: 1.5rem;
        }

        .content p {
            font-size: 0.95rem;
            margin: 0.5rem 0;
        }

        .content ul {
            list-style-type: disc;
            margin: 0.5rem 0 1rem 1.5rem;
        }

        .content li {
            margin-bottom: 0.5rem;
            font-size: 0.95rem;
        }

        .content a {
            color: #c36;
            text-decoration: none;
            transition: color 0.3s ease;
        }

        .content a:hover {
            color: #336;
        }

        /* Accordion Styles */
        details {
            margin-bottom: 1rem;
            border: 1px solid #e0e0e0;
            border-radius: 8px;
            background-color: var(--light-grey);
            transition: all 0.3s ease;
        }

        details[open] {
            border-color: var(--green);
        }

        summary {
            cursor: pointer;
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--black);
            padding: 0.75rem 1rem;
            display: flex;
            justify-content: space-between;
            align-items: center;
            outline: none;
        }

        summary::after {
            content: '▼';
            font-size: 0.8rem;
            color: var(--black);
            transition: transform 0.3s ease;
        }

        details[open] summary::after {
            transform: rotate(180deg);
        }

        summary:hover {
            color: var(--green);
        }

        details[open] summary {
            color: var(--green);
        }

        .accordion-content {
            padding: 1rem;
            font-size: 0.95rem;
        }

        .accordion-content h3 {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--black);
            margin: 0.75rem 0 0.5rem;
        }

        /* Back to Top Button */
        .back-to-top {
            display: inline-block;
            background-color: transparent;
            border: 1px solid var(--black);
            color: var(--black);
            font-family: 'Montserrat', sans-serif;
            font-weight: 600;
            font-size: 0.9rem;
            border-radius: 8px;
            padding: 8px 16px;
            text-align: center;
            text-decoration: none;
            margin: 1.5rem 0;
            transition: all 0.3s ease;
        }

        .back-to-top:hover,
        .back-to-top:focus {
            background-color: var(--black);
            border-color: var(--white);
            color: var(--white);
        }

        /* Responsive Design */
        @media (max-width: 768px) {
            .privacy-policy-container {
                flex-direction: column;
                margin: 1rem;
                padding: 15px;
            }
            .table-of-contents {
                display: none; /* Hide table of contents on mobile */
            }
            .content {
                width: 100%;
            }
            .content h1 {
                font-size: 1.8rem;
            }
            .content h2,
            summary {
                font-size: 1rem;
            }
            .content h3 {
                font-size: 0.95rem;
            }
            .content p,
            .content li,
            .accordion-content {
                font-size: 0.9rem;
            }
            .back-to-top {
                font-size: 0.8rem;
                padding: 6px 12px;
            }
        }
    </style>
</head>
<body>
    <div class="privacy-policy-container">
        <nav class="table-of-contents">
            <h2>Table of Contents</h2>
            <ul>
                <li><a href="#information-we-collect">1. Information We Collect</a></li>
                <li><a href="#how-we-use">2. How We Use Your Information</a></li>
                <li><a href="#how-we-share">3. How We Share Your Information</a></li>
                <li><a href="#your-privacy-rights">4. Your Privacy Rights</a></li>
                <li><a href="#security-and-storage">5. Security and Data Storage</a></li>
                <li><a href="#childrens-privacy">6. Children's Privacy</a></li>
                <li><a href="#international-transfers">7. International Data Transfers</a></li>
                <li><a href="#changes-to-policy">8. Changes to This Privacy Policy</a></li>
                <li><a href="#contact-us">9. Contact Us</a></li>
                <li><a href="#faqs">10. Frequently Asked Questions</a></li>
            </ul>
        </nav>

        <div class="content">
            <h1>Privacy Policy for Jenga365</h1>
            <p class="last-updated">Last Updated: September 24, 2025</p>
            <p>Jenga365.com ("we," "us," or "our") is a mentoring platform connecting individuals in sports and careers, based in Nairobi, Kenya. We prioritize your privacy, handling sensitive sports and career data transparently. By using our platform, you agree to this Privacy Policy.</p>

            <section id="information-we-collect">
                <details>
                    <summary>1. Information We Collect</summary>
                    <div class="accordion-content">
                        <p>We collect only the data necessary for mentoring, event management, and platform improvement.</p>
                        <h3>Personal Information You Provide</h3>
                        <ul>
                            <li><strong>Registration and Profile</strong>: Name, email, phone, profile photo, sports background (e.g., discipline, achievements), career details (e.g., resume, goals).</li>
                            <li><strong>Events</strong>: Webinar or clinic registration and attendance data.</li>
                            <li><strong>Communications</strong>: Contact forms, emails, social media interactions.</li>
                        </ul>
                        <h3>Sensitive Information</h3>
                        <p>Collected with explicit consent:</p>
                        <ul>
                            <li><strong>Sports Metrics</strong>: Training logs, injury history, performance goals.</li>
                            <li><strong>Career Preferences</strong>: Detailed career goals for matching.</li>
                        </ul>
                        <h3>Automatically Collected Data</h3>
                        <ul>
                            <li><strong>Technical Data</strong>: IP address, device, browser, operating system.</li>
                            <li><strong>Browsing Activity</strong>: Pages visited, links clicked, content viewed, timestamps.</li>
                            <li><strong>Social Integrations</strong>: Data from Google, Facebook, LinkedIn, Twitter, Instagram via social login, per your privacy settings.</li>
                        </ul>
                        <h3>Cookies</h3>
                        <p>We use cookies for analytics and functionality:</p>
                        <ul>
                            <li><strong>Necessary (Session)</strong>: Enable core features, authentication.</li>
                            <li><strong>Functionality (Persistent)</strong>: Save login details, preferences.</li>
                            <li><strong>Analytics (Persistent)</strong>: Track usage to improve the platform.</li>
                        </ul>
                        <p>Manage cookies via browser settings or our <a href="#cookies-policy">Cookies Policy</a>.</p>
                    </div>
                </details>
            </section>

            <section id="how-we-use">
                <details>
                    <summary>2. How We Use Your Information</summary>
                    <div class="accordion-content">
                        <p>We use your data (per GDPR/CCPA legal bases) to:</p>
                        <ul>
                            <li><strong>Provide Services</strong>: Create accounts, match mentors/mentees, manage events, deliver content.</li>
                            <li><strong>Personalize</strong>: Recommend content, improve functionality.</li>
                            <li><strong>Communicate</strong>: Send notifications, marketing emails (with consent).</li>
                            <li><strong>Social Features</strong>: Enable sharing, social logins (e.g., LinkedIn).</li>
                            <li><strong>Security</strong>: Prevent fraud, ensure safety.</li>
                        </ul>
                    </div>
                </details>
            </section>

            <section id="how-we-share">
                <details>
                    <summary>3. How We Share Your Information</summary>
                    <div class="accordion-content">
                        <p>We do not sell data. We share it only when:</p>
                        <ul>
                            <li><strong>Matched Users</strong>: Profile/contact details with mentors/mentees, with consent.</li>
                            <li><strong>Service Providers</strong>: Vendors (e.g., AWS, Zoom, Mailchimp) under strict agreements.</li>
                            <li><strong>Business Transfers</strong>: During mergers, with notice.</li>
                            <li><strong>Legal Requirements</strong>: For compliance or to protect rights/safety.</li>
                            <li><strong>With Consent</strong>: For other purposes with permission.</li>
                        </ul>
                    </div>
                </details>
            </section>

            <section id="your-privacy-rights">
                <details>
                    <summary>4. Your Privacy Rights</summary>
                    <div class="accordion-content">
                        <p>Under GDPR, CCPA, and Kenya’s Data Protection Act, 2019, you can:</p>
                        <ul>
                            <li><strong>Access</strong>: Request your data.</li>
                            <li><strong>Rectify</strong>: Correct inaccurate data.</li>
                            <li><strong>Delete</strong>: Request deletion, subject to legal retention.</li>
                            <li><strong>Object</strong>: Opt out of marketing or processing.</li>
                            <li><strong>Portability</strong>: Receive data in a machine-readable format.</li>
                            <li><strong>Opt-Out of Sale</strong>: We don’t sell data, but you can opt out of future sales.</li>
                        </ul>
                        <p>Email <a href="mailto:privacy@jenga365.com">privacy@jenga365.com</a> or use your dashboard. We respond within 30 days after verification.</p>
                    </div>
                </details>
            </section>

            <section id="security-and-storage">
                <details>
                    <summary>5. Security and Data Storage</summary>
                    <div class="accordion-content">
                        <p>We protect your data with:</p>
                        <ul>
                            <li><strong>HTTPS</strong>: Encrypts transmission.</li>
                            <li><strong>Access Controls</strong>: Limits internal access.</li>
                            <li><strong>End-to-End Encryption</strong>: Planned for mentoring chats.</li>
                            <li><strong>Audits</strong>: Regular security checks.</li>
                        </ul>
                        <p><strong>Retention</strong>: Data kept only as needed, purged within 60 days of deletion.</p>
                        <p><strong>Breach Notification</strong>: We notify within 72 hours of a breach (per GDPR).</p>
                    </div>
                </details>
            </section>

            <section id="childrens-privacy">
                <details>
                    <summary>6. Children's Privacy</summary>
                    <div class="accordion-content">
                        <p>Jenga365 is for users 16+. Youth programs require parental consent for under-16s. We don’t collect data from under-13s. Contact <a href="mailto:privacy@jenga365.com">privacy@jenga365.com</a> for issues.</p>
                    </div>
                </details>
            </section>

            <section id="international-transfers">
                <details>
                    <summary>7. International Data Transfers</summary>
                    <div class="accordion-content">
                        <p>Data may transfer globally (e.g., U.S. to EU). We use Standard Contractual Clauses for GDPR compliance.</p>
                    </div>
                </details>
            </section>

            <section id="changes-to-policy">
                <details>
                    <summary>8. Changes to This Privacy Policy</summary>
                    <div class="accordion-content">
                        <p>We may update this policy, notifying you via:</p>
                        <ul>
                            <li>Email.</li>
                            <li>Banner on <a href="https://jenga365.com">jenga365.com</a>.</li>
                            <li>Updates at <a href="https://jenga365.com/privacy-policy">jenga365.com/privacy-policy</a>.</li>
                        </ul>
                        <p>Continued use indicates acceptance.</p>
                    </div>
                </details>
            </section>

            <section id="contact-us">
                <details>
                    <summary>9. Contact Us</summary>
                    <div class="accordion-content">
                        <p>Contact our Privacy Team:</p>
                        <ul>
                            <li><strong>Email</strong>: <a href="mailto:privacy@jenga365.com">privacy@jenga365.com</a></li>
                            <li><strong>Website</strong>: <a href="https://jenga365.com/contact-2/">jenga365.com/contact-2/</a></li>
                        </ul>
                        <p>File complaints with Kenya’s Office of the Data Protection Commissioner.</p>
                    </div>
                </details>
            </section>

            <section id="faqs">
                <details>
                    <summary>10. Frequently Asked Questions</summary>
                    <div class="accordion-content">
                        <h3>How is my data handled in mentoring sessions?</h3>
                        <p>Sessions are confidential. Chats will use end-to-end encryption (when implemented). Third-party platforms (e.g., Zoom) follow their privacy policies.</p>
                        <h3>Are my resume or metrics public?</h3>
                        <p>No, sensitive data is shared only with matched mentors/mentees, with consent.</p>
                        <h3>Why use social media data?</h3>
                        <p>For login and sharing features (e.g., LinkedIn, Twitter), limited by your privacy settings.</p>
                    </div>
                </details>
            </section>

            <section id="cookies-policy">
                <details>
                    <summary>Cookies Policy</summary>
                    <div class="accordion-content">
                        <p>We use cookies to enhance your experience. Manage preferences via browser settings or our consent tool. See <a href="https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking">Free Privacy Policy</a>.</p>
                    </div>
                </details>
            </section>

            <a href="#top" class="back-to-top">Back to Top</a>
        </div>
    </div>

    <script>
        // Accordion: Close other details when one is opened
        document.querySelectorAll('.privacy-policy-container details').forEach(detail => {
            detail.addEventListener('toggle', function () {
                if (this.open) {
                    document.querySelectorAll('.privacy-policy-container details').forEach(d => {
                        if (d !== this) d.removeAttribute('open');
                    });
                }
            });
        });

        // Table of Contents Active State
        const links = document.querySelectorAll('.table-of-contents a');
        const sections = document.querySelectorAll('.content section');
        window.addEventListener('scroll', () => {
            let current = '';
            sections.forEach(section => {
                const sectionTop = section.offsetTop;
                if (pageYOffset >= sectionTop - 60) {
                    current = section.getAttribute('id');
                }
            });
            links.forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('href').substring(1) === current) {
                    link.classList.add('active');
                }
            });
        });
    </script>
</body>
</html>"},"elements":[],"widgetType":"text-editor"}],"isInner":false}]

